//! The C definitions of the libraries this crate loads, generated from their headers.
//!
//! Every number and structure the crate hands `libcuda.so.1`, `libnvidia-ml.so.1`,
//! `libnccl.so.2` or `libcupti.so.13` comes from these modules rather than being typed by hand: a
//! wrong number in a binding is not a compile error but a refused call, a silently ignored
//! attribute or a wrong computation. The files are generated by `examples/bindings.rs` from the
//! headers of the versions the crate is written for and committed, because the crate opens the
//! libraries at run time and builds on hosts without the CUDA toolkit. Each file states the
//! version of the header it came from (`CUDA_VERSION`, `NCCL_VERSION_CODE`,
//! `CUPTI_API_VERSION`).
//!
//! bindgen's layout assertions in each file compare every structure's size, alignment and field
//! offsets with the header's on the target being compiled, so a target whose C layout differs
//! from the header's fails to build instead of passing wrong structures.

/// `cuda.h` of CUDA 13.0: the driver API.
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unreachable_pub,
    clippy::all,
    clippy::undocumented_unsafe_blocks,
    unused_imports
)]
#[rustfmt::skip]
pub(crate) mod cuda;

